  `Revisado` int(11) NOT NULL DEFAULT '0',
  `AutorizadoIndex` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`idFeed`)
) ENGINE=InnoDB AUTO_INCREMENT=4162 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
